\[\mathbf{R} = \frac{1}{1^2 + 5^2} \begin{pmatrix} 2(1)^2 - (1^2 + 5^2) & 2(1)(5) \\ 2(1)(5) & 2(5)^2 - (1^2 + 5^2) \end{pmatrix}.\]

